"""lstm_classifier - training script generated by AI Made Easy."""
import time

import numpy as np
import torch
import torch.nn as nn
from torch.utils.data import DataLoader, TensorDataset

# ------------------------------------------------------------------ config
SEED = 42
DEVICE = "auto"
EPOCHS = 15
BATCH_SIZE = 32
EARLY_STOP = 4
VAL_FRACTION = 0.1
TEST_FRACTION = 0.1
NUM_WORKERS = 0
PIN_MEMORY = True
CHECKPOINT = "lstm_classifier_best.pt"
INPUT_SHAPE = (50, 32)

def pick_device() -> str:
    if DEVICE != "auto":
        return DEVICE
    if torch.backends.mps.is_available():
        return "mps"
    if torch.cuda.is_available():
        return "cuda"
    return "cpu"


# ------------------------------------------------------------------- model
class LstmClassifier(nn.Module):
    def __init__(self):
        super().__init__()
        self.lstm_1 = nn.LSTM(input_size=32, hidden_size=48, num_layers=1, bias=True, batch_first=True, bidirectional=False)
        self.dropout_1 = nn.Dropout(p=0.2)
        self.dense_1 = nn.Linear(in_features=48, out_features=5, bias=True)

    def forward(self, x):
        v_lstm_1 = self.lstm_1(x)[0]
        v_dropout_1 = self.dropout_1(v_lstm_1)
        v_mean_over_time_1 = torch.mean(v_dropout_1, dim=1)
        v_dense_1 = self.dense_1(v_mean_over_time_1)
        return v_dense_1


# ----------------------------------------------------------------- dataset

def make_arrays():
    """Synthetic classification data"""
    rng = np.random.default_rng(SEED)
    n, d, k = 1000, 1600, 5
    centers = rng.normal(scale=2.0, size=(k, d))
    y = rng.integers(0, k, size=n)
    x = (centers[y] + rng.normal(scale=0.5, size=(n, d))).astype(np.float32)
    x = x.reshape(n, *INPUT_SHAPE)
    return x, y


def make_loaders(device_hint: str):
    x, y = make_arrays()
    x = x.astype(np.float32)
    y = y.astype(np.int64)
    n = len(x)
    idx = np.random.default_rng(SEED).permutation(n)
    n_val = int(n * VAL_FRACTION)
    n_test = int(n * TEST_FRACTION)
    val_i = idx[:n_val]
    test_i = idx[n_val:n_val + n_test]
    train_i = idx[n_val + n_test:]
    mk = lambda ids: DataLoader(
        TensorDataset(torch.from_numpy(x[ids]), torch.from_numpy(y[ids])),
        batch_size=BATCH_SIZE, shuffle=True,
        num_workers=NUM_WORKERS, pin_memory=PIN_MEMORY)
    return mk(train_i), mk(val_i), mk(test_i)


N_CLASSES = 5


def class_metrics(preds: torch.Tensor, targets: torch.Tensor):
    """Confusion-matrix based macro precision/recall/F1."""
    cm = torch.bincount(targets * N_CLASSES + preds, minlength=N_CLASSES ** 2)
    cm = cm.reshape(N_CLASSES, N_CLASSES).float()
    tp = cm.diag()
    precision = tp / (cm.sum(0) + 1e-12)
    recall = tp / (cm.sum(1) + 1e-12)
    f1 = 2 * precision * recall / (precision + recall + 1e-12)
    return precision.mean().item(), recall.mean().item(), f1.mean().item(), cm.long()



@torch.no_grad()
def evaluate(model, loss_fn, loader, device):
    model.eval()
    total, n_seen = 0.0, 0
    all_p, all_t = [], []
    for xb, yb in loader:
        xb, yb = xb.to(device), yb.to(device)
        out = model(xb)
        total += loss_fn(out, yb).item() * len(yb)
        n_seen += len(yb)
        all_p.append(out.argmax(1).cpu())
        all_t.append(yb.cpu())
    metrics = {}
    p, t = torch.cat(all_p), torch.cat(all_t)
    metrics["accuracy"] = (p == t).float().mean().item()
    prec, rec, f1, cm = class_metrics(p, t)
    metrics["precision"] = prec
    metrics["recall"] = rec
    metrics["f1"] = f1
    return total / max(n_seen, 1), metrics




def main():
    torch.manual_seed(SEED)
    np.random.seed(SEED)
    device = torch.device(pick_device())
    print(f"device: {device}")
    train_loader, val_loader, test_loader = make_loaders(str(device))
    model = LstmClassifier().to(device)
    print(f"parameters: {sum(p.numel() for p in model.parameters()):,}")
    loss_fn = nn.CrossEntropyLoss(label_smoothing=0.0)
    optimizer = torch.optim.RAdam(model.parameters(), lr=0.001, betas=(0.9, 0.999))
    scheduler = torch.optim.lr_scheduler.OneCycleLR(optimizer, max_lr=0.01, total_steps=EPOCHS * len(train_loader), pct_start=0.3)
    best_val, best_state, bad_epochs = float("inf"), None, 0
    for epoch in range(1, EPOCHS + 1):
        model.train()
        t0, running = time.time(), 0.0
        for xb, yb in train_loader:
            xb, yb = xb.to(device), yb.to(device)
            optimizer.zero_grad()
            loss = loss_fn(model(xb), yb)
            loss.backward()
            optimizer.step()
            scheduler.step()
            running += loss.item() * len(xb)
        train_loss = running / len(train_loader.dataset)
        val_loss, val_metrics = evaluate(model, loss_fn, val_loader, device)
        extra = " ".join(f"{k}={v:.4f}" if isinstance(v, float) else f"{k}={v}"
                         for k, v in val_metrics.items())
        print(f"epoch {epoch}/{EPOCHS} train_loss={train_loss:.4f} "
              f"val_loss={val_loss:.4f} {extra} ({time.time() - t0:.1f}s)")
        if val_loss < best_val:
            best_val, bad_epochs = val_loss, 0
            best_state = {k: v.detach().cpu().clone() for k, v in model.state_dict().items()}
        else:
            bad_epochs += 1
            if EARLY_STOP and bad_epochs >= EARLY_STOP:
                print(f"early stopping after {epoch} epochs without improvement")
                break
    if best_state is not None:
        model.load_state_dict(best_state)
    test_loss, test_metrics = evaluate(model, loss_fn, test_loader, device)
    print("test:", {**test_metrics, "loss": round(test_loss, 4)})
    torch.save(model.state_dict(), CHECKPOINT)
    print(f"saved best weights to {CHECKPOINT}")


if __name__ == "__main__":
    main()
